impl Drop for DurableUnboundPlanningV1{fn drop(&mut self){assert!(std::thread::panicking()||(self.wire.is_none()&&self.pack.is_none()&&self.closing_wire.is_none()&&self.closing_pack.is_none()),"durable member planning must retire or transfer every paid output before Drop");}}
